//! The app icon at runtime: the window icon (title bar, taskbar and
//! app switcher on Windows and X11) and the macOS Dock icon, in the
//! `app_icon` colourway. Bundles and packages carry the default's own copies
//! (`.icns`, hicolor PNGs, `.ico`), all generated by `packaging/gen-icon.py`;
//! on macOS the Dock tile plugin in `Rift.app` (`packaging/docktile/`) shows
//! the chosen icon while Rift is not running.

use rift_core::AppIcon;

/// 256 px RGBA PNG written by `packaging/gen-icon.py`.
const PNG: &[u8] = include_bytes!("../../../assets/icon/rift-window.png");

/// The 512 px colourways (`packaging/gen-icon.py` `VARIANTS`).
fn variant_png(icon: AppIcon) -> &'static [u8] {
    match icon {
        AppIcon::Default => include_bytes!("../../../assets/icon/variants/default.png"),
        AppIcon::Light => include_bytes!("../../../assets/icon/variants/light.png"),
        AppIcon::Mono => include_bytes!("../../../assets/icon/variants/mono.png"),
        AppIcon::Ocean => include_bytes!("../../../assets/icon/variants/ocean.png"),
        AppIcon::Ember => include_bytes!("../../../assets/icon/variants/ember.png"),
        AppIcon::Forest => include_bytes!("../../../assets/icon/variants/forest.png"),
        AppIcon::Neon => include_bytes!("../../../assets/icon/variants/neon.png"),
    }
}

/// The PNG for `icon`: the 256 px window icon for the default.
fn png_of(icon: AppIcon) -> &'static [u8] {
    match icon {
        AppIcon::Default => PNG,
        other => variant_png(other),
    }
}

/// Decode a PNG to (RGBA bytes, width, height).
fn rgba(png: &[u8]) -> Option<(Vec<u8>, u32, u32)> {
    let mut reader = png::Decoder::new(std::io::Cursor::new(png))
        .read_info()
        .ok()?;
    let mut buf = vec![0; reader.output_buffer_size()?];
    let info = reader.next_frame(&mut buf).ok()?;
    if info.color_type != png::ColorType::Rgba || info.bit_depth != png::BitDepth::Eight {
        return None;
    }
    buf.truncate(info.buffer_size());
    Some((buf, info.width, info.height))
}

/// The window icon in `icon`'s colourway; `None` only if the embedded PNG
/// is unusable.
pub fn window_icon(icon: AppIcon) -> Option<winit::window::Icon> {
    let (rgba, w, h) = rgba(png_of(icon))?;
    winit::window::Icon::from_rgba(rgba, w, h).ok()
}

/// Show `icon` in the Dock. The default inside `Rift.app` is the bundle's
/// own `.icns` (no override); an unbundled run (`cargo run`) always sets
/// one. Inside the bundle the choice is also stored for the Dock tile
/// plugin (`AppIcon` in the app's defaults) and the plugin is told.
#[cfg(target_os = "macos")]
pub fn set_dock_icon(icon: AppIcon) {
    use objc2::rc::Retained;
    use objc2::runtime::AnyObject;
    use objc2::{AllocAnyThread, MainThreadMarker, class, msg_send};
    use objc2_app_kit::{NSApplication, NSImage};
    use objc2_foundation::{NSData, NSString};

    let bundled = std::env::current_exe()
        .map(|p| p.to_string_lossy().contains(".app/Contents/MacOS/"))
        .unwrap_or(false);
    let Some(mtm) = MainThreadMarker::new() else {
        return;
    };
    let app = NSApplication::sharedApplication(mtm);
    if bundled {
        // SAFETY: the standard defaults and the distributed center exist in
        // every process; the messages take an object (or nil) and strings
        unsafe {
            let defaults: Retained<AnyObject> =
                msg_send![class!(NSUserDefaults), standardUserDefaults];
            let key = NSString::from_str("AppIcon");
            let value = NSString::from_str(icon.name());
            let _: () = msg_send![&*defaults, setObject: &*value, forKey: &*key];
            let _: bool = msg_send![&*defaults, synchronize];
            let center: Retained<AnyObject> =
                msg_send![class!(NSDistributedNotificationCenter), defaultCenter];
            let name = NSString::from_str("dev.rift.terminal.AppIconChanged");
            let none: Option<&AnyObject> = None;
            let _: () = msg_send![
                &*center,
                postNotificationName: &*name,
                object: none,
                userInfo: none,
                deliverImmediately: true
            ];
        }
        if icon == AppIcon::Default {
            // SAFETY: main thread (checked above); nil restores the bundle icon
            unsafe { app.setApplicationIconImage(None) };
            return;
        }
    }
    let data = NSData::with_bytes(png_of(icon));
    if let Some(image) = NSImage::initWithData(NSImage::alloc(), &data) {
        // SAFETY: main thread (checked above); the image is a valid NSImage.
        unsafe { app.setApplicationIconImage(Some(&image)) };
        log::info!("dock icon: {}", icon.name());
    } else {
        log::warn!("dock icon: embedded PNG rejected by NSImage");
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_icon_decodes_to_square_rgba() {
        let (rgba, w, h) = super::rgba(PNG).expect("icon decodes");
        assert_eq!((w, h), (256, 256));
        assert_eq!(rgba.len(), 256 * 256 * 4);
        assert!(window_icon(AppIcon::Default).is_some());
    }

    #[test]
    fn every_colourway_decodes_and_differs() {
        let mut seen = std::collections::HashSet::new();
        for icon in AppIcon::ALL {
            let (rgba, w, h) = super::rgba(variant_png(icon))
                .unwrap_or_else(|| panic!("{} does not decode", icon.name()));
            assert_eq!((w, h), (512, 512), "{}", icon.name());
            // the tile's centre colour tells the colourways apart
            let mid = ((256 * 512 + 256) * 4) as usize;
            assert!(
                seen.insert(rgba[mid - 4 * 120..mid - 4 * 120 + 3].to_vec()),
                "{}",
                icon.name()
            );
            assert!(window_icon(icon).is_some());
        }
    }
}
